use std::fs

fn find(names: Vec<string>, n: string) -> int {
    let mut i: int = 0
    while i < names.len() as int {
        if names[i as usize] == n {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut bals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() < 2 {
            continue
        }
        let cmd = parts[0]
        let n = parts[1]
        if cmd == "balance" {
            let i = find(names, n)
            if i >= 0 {
                println("${bals[i as usize]}")
            } else {
                println("error: unknown account ${n}")
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let t = parts[2]
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            let fi = find(names, n)
            let ti = find(names, t)
            if amt <= 0 {
                println("error: invalid amount")
            } else if fi < 0 {
                println("error: unknown account ${n}")
            } else if ti < 0 {
                println("error: unknown account ${t}")
            } else if fi == ti {
                println("error: same account")
            } else if bals[fi as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[fi as usize] = bals[fi as usize] - amt
                bals[ti as usize] = bals[ti as usize] + amt
                println("ok")
            }
        } else if parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            let i = find(names, n)
            if cmd == "open" {
                if amt < 0 {
                    println("error: invalid amount")
                } else if i >= 0 {
                    println("error: duplicate account")
                } else {
                    names.push(n)
                    bals.push(amt)
                    println("ok")
                }
            } else if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${n}")
            } else if cmd == "deposit" {
                bals[i as usize] = bals[i as usize] + amt
                println("ok")
            } else if bals[i as usize] < amt {
                println("error: insufficient funds")
            } else {
                bals[i as usize] = bals[i as usize] - amt
                println("ok")
            }
        }
    }
    let mut order: Vec<string> = names
    order.sort()
    for k in order {
        let i = find(names, k)
        println("${k} ${bals[i as usize]}")
    }
}

