use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() < 2 {
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "balance" {
            let n = parts[1].clone()
            if acc.contains_key(n) {
                println("${acc.get(n).unwrap_or(0)}")
            } else {
                println("error: unknown account ${n}")
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let f = parts[1].clone()
            let t = parts[2].clone()
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(f) {
                println("error: unknown account ${f}")
            } else if !acc.contains_key(t) {
                println("error: unknown account ${t}")
            } else if f == t {
                println("error: same account")
            } else {
                let fb = acc.get(f).unwrap_or(0)
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    let tb = acc.get(t).unwrap_or(0)
                    acc.insert(f, fb - amt)
                    acc.insert(t, tb + amt)
                    println("ok")
                }
            }
        } else if parts.len() >= 3 {
            let n = parts[1].clone()
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if cmd == "open" {
                if amt < 0 {
                    println("error: invalid amount")
                } else if acc.contains_key(n) {
                    println("error: duplicate account")
                } else {
                    acc.insert(n, amt)
                    println("ok")
                }
            } else if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n) {
                println("error: unknown account ${n}")
            } else {
                let b = acc.get(n).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(n, b + amt)
                    println("ok")
                } else if b < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n, b - amt)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().map(|k| k.to_string()).collect()
    keys.sort()
    for k in keys {
        println("${k} ${acc.get(k).unwrap_or(0)}")
    }
}
